            gen = tool.streaming_executor(db, args if isinstance(args, dict) else {})
            for phase_name, phase_data in gen:
                if phase_name == "__final__":
                    final_result = phase_data
                    continue
                yield (
                    "tool_phase",
                    {
                        "id": tc["id"],
                        "name": name,
                        "phase": phase_name,
                        **phase_data,
                    },
